PRAGMA foreign_keys=ON;
CREATE TABLE users(id INTEGER PRIMARY KEY);
CREATE TABLE children(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX users_idx ON users(id);
INSERT INTO users VALUES(1);
INSERT INTO children VALUES(1);
CREATE TABLE backup1(id INTEGER);
INSERT INTO backup1 SELECT * FROM users;
CREATE TABLE backup2(id INTEGER);
INSERT INTO backup2 SELECT * FROM users;
DROP TABLE users;
CREATE TABLE users(id INTEGER PRIMARY KEY, label TEXT);
INSERT INTO users(id) SELECT * FROM backup1;
INSERT OR IGNORE INTO users(id) SELECT * FROM backup2;
DROP TABLE backup1;
DROP TABLE backup2;
